#!/usr/bin/env python3
"""patch_dressing_scene.py -- the manifest becomes a scene. Piece 5 of 5.

level_factory 0.44.0 -> 0.45.0. Requires `patch_lf_release_044.py` first.

    zoo    --measure_shapes         -> metrics.json       (Zoo 0.38.0)
    lot    site_surfaces            -> surfaces.json      (Lot 0.46.0)
    patina --mode surface_dressing  -> surface_dressing   (Patina 0.21.0)
    dressing_scene                  -> <site>_dressing.tscn        <- this

MEASURED ON THE REAL PLAN. coldrun_pawn_job, 3,948 placements of four species:

    multimesh   4 draw calls,     326 KB scene
    nodes    3,948 draw calls,    888 KB scene

The second number is what one `MeshInstance3D` per placement costs, and it is
the load hitch this layer was told not to cause. Four meshes repeated
thousands of times is the case instancing exists for.

A SEPARATE SCENE, NOT NODES IN THE SITE. `<site>_dressing.tscn` is written
alongside the site scene for the site to instance. The site scene is the
functional shell and the shell is LOCKED -- a dressing pass that edits it has
broken the one promise this layer makes, whatever the geometry does.

BOTH GATES ARE RE-CHECKED HERE, at the last stage, deliberately. A manifest is
data and data travels; the gate that matters is the one standing where the
geometry is about to become real. A collider in the manifest, a Y-up manifest,
or a placement over `unassisted_step_max` in traversed space each refuse to
write rather than writing something wrong.

THE COORDINATE CONVERSION IS TRANSCRIBED FROM LOT, NOT RE-DERIVED.
`lot.py:_godot_transform` already solved Z-up -> Y-up and ships it on
hardware: site XY -> Godot XZ, site Z -> Godot Y, origin (x,y,z) -> (x,z,-y),
and yaw about site Z becomes yaw about Godot Y NEGATED, because the axis swap
flips handedness. That negation is the whole game and it is not obvious.
Re-deriving it would have given this repo two answers to a question it has
already answered once -- and this session has already shown what happens when
I reason from my own copy instead of the source. The tests pin it at yaw 0 and
yaw 90, where the answer is known by inspection.

TWO THINGS THIS MODULE CANNOT VERIFY WITHOUT GODOT, AND SAYS SO INSTEAD OF
ASSERTING THEM:

  1. The MultiMesh buffer layout -- which 12 floats, in which order. Isolated
     in `multimesh_floats()`: one function, one docstring, one test. If the
     engine disagrees, that function changes and nothing else does.
     `--mode nodes` emits the same transforms as ordinary MeshInstance3D
     nodes using the `Transform3D` string Lot already ships, so the two can be
     opened side by side in the editor and compared in one look. That is the
     check I want run before this is trusted.

  2. How a mesh resource is addressed. A `.glb` imports as a PackedScene and a
     MultiMesh needs a Mesh, so whether it is a `.tres`, a `.res`, or a
     `res://x.glb::Mesh_y` subresource path depends on your import settings.
     The caller supplies the path per asset; an asset without one is an
     ERROR, because a dressing layer missing a species is not a smaller layer.

23 tests. Nothing imports this yet -- wiring it into a job is the next
decision, not this patch's.

    python patch_dressing_scene.py --check
    python patch_dressing_scene.py --selftest
    python patch_dressing_scene.py
    python patch_dressing_scene.py --revert
"""
