def repo_root(start=None):
    d = os.path.abspath(start or os.path.dirname(os.path.abspath(__file__)))
    for _ in range(8):
        if (os.path.isdir(os.path.join(d, "level_factory", "packages"))
                and os.path.isfile(os.path.join(d, "level_factory",
                                                "VERSION"))):
            return d
        nd = os.path.dirname(d)
        if nd == d:
            break
        d = nd
    return None


def sha(b):
    return hashlib.sha256(b).hexdigest()


def rd(p):
    with open(p, "rb") as fh:
        return fh.read()


def wr(p, b):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "wb") as fh:
        fh.write(b)


def plan(root):
    rows, ok = [], True
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        exists = os.path.isfile(p)
        if d["kind"] == "new":
            if exists and sha(rd(p)) == d["post_sha"]:
                rows.append((rel, "already-current", True))
            elif exists:
                rows.append((rel, "EXISTS AND DIFFERS - refusing", False))
                ok = False
            else:
                rows.append((rel, f"create {d['post_bytes']} B", True))
            continue
        if not exists:
            rows.append((rel, "MISSING - refusing", False))
            ok = False
            continue
        cur = sha(rd(p))
        if cur == d["post_sha"]:
            rows.append((rel, "already-current", True))
        elif cur == d["pre_sha"]:
            rows.append((rel, f"replace {d['pre_bytes']} -> {d['post_bytes']} B",
                         True))
        else:
            rows.append((rel, f"DRIFT sha {cur[:12]} != {d['pre_sha'][:12]}",
                         False))
            ok = False
    return ok, rows


def show(rows):
    w = max(len(r[0]) for r in rows)
    for rel, msg, good in rows:
        print(f"  {'ok ' if good else 'STOP'}  {rel:<{w}}  {msg}")


def apply(root):
    ok, rows = plan(root)
    show(rows)
    if not ok:
        print("\nREFUSING: nothing written. Resolve the lines marked STOP.")
        return 1
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        if os.path.isfile(p):
            cur = rd(p)
            if sha(cur) == d["post_sha"]:
                continue
            side = p + SIDECAR
            if not os.path.exists(side):
                wr(side, cur)
        wr(p, base64.b64decode(d["b64"]))
        assert sha(rd(p)) == d["post_sha"], rel
        n += 1
    print(f"\nWROTE {n} file(s). Sidecars: *{SIDECAR}")
    print("Next:")
    print("  cd level_factory")
    print("  python -m pytest tests/test_dressing_scene.py    # 23")
    print("  python -m pytest tests")
    print("Then the check I actually want, in Godot: write the same manifest")
    print("both ways and open them side by side --")
    print("  python -m packages.exporting.dressing_scene <manifest> \\")
    print("      --mesh-paths paths.json --out d.tscn")
    print("  ... --mode nodes --out d_nodes.tscn")
    print("If they look identical, the MultiMesh buffer layout is right.")
    return 0


def revert(root):
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        side = p + SIDECAR
        if os.path.exists(side):
            wr(p, rd(side))
            os.remove(side)
            print(f"  reverted {rel}")
            n += 1
        elif d["kind"] == "new" and os.path.isfile(p):
            if sha(rd(p)) == d["post_sha"]:
                os.remove(p)
                print(f"  removed  {rel} (this patch created it)")
                n += 1
            else:
                print(f"  KEPT     {rel} (modified since; not ours to delete)")
    print(f"reverted {n} file(s)")
    return 0


def selftest():
    bad = 0

    def fail(msg):
        nonlocal bad
        print(f"  FAIL  {msg}")
        bad += 1

    print("patch_dressing_scene selftest")

    for rel, d in PAYLOAD.items():
        b = base64.b64decode(d["b64"])
        if sha(b) != d["post_sha"] or len(b) != d["post_bytes"]:
            fail(f"payload {rel} does not match its recorded hash/size")
    print(f"  ok    {len(PAYLOAD)} payloads decode to their recorded hashes")

    import ast

    def src(rel):
        return base64.b64decode(PAYLOAD[rel]["b64"]).decode("utf-8")

    mod = src("level_factory/packages/exporting/dressing_scene.py")
    tst = src("level_factory/tests/test_dressing_scene.py")
    tree = ast.parse(mod)
    funcs = {n.name for n in tree.body if isinstance(n, ast.FunctionDef)}
    for want in ("godot_transform", "multimesh_floats", "transform3d_string",
                 "check_manifest", "scene_text", "summarise", "main"):
        if want not in funcs:
            fail(f"dressing_scene has no {want}()")
    print("  ok    the module exposes its conversion, its gates and a CLI")

    # FALSIFICATION: the handedness flip must be PRESENT. Without the negated
    # sine the scene still writes, still validates, and every object in it is
    # mirrored -- the failure mode that looks fine until someone walks it.
    if "-s * k" not in mod and "-s*k" not in mod:
        fail("the basis has no negated sine; the Z-up -> Y-up handedness flip "
             "is missing and every placement would be mirrored")
    if "-float(pos[1])" not in mod:
        fail("the origin does not negate site y; site (x,y,z) -> Godot "
             "(x, z, -y)")
    print("  ok    the handedness flip and the y negation are both there")

    # The one unverifiable assumption must be isolated AND labelled, so the
    # next person knows where to look rather than reading the whole file.
    mm = next((n for n in tree.body if isinstance(n, ast.FunctionDef)
               and n.name == "multimesh_floats"), None)
    doc = ast.get_docstring(mm) or ""
    if "ASSUMPTION" not in doc.upper():
        fail("multimesh_floats does not declare itself the assumption")
    if "nodes" not in mod or "MeshInstance3D" not in mod:
        fail("there is no nodes mode to compare the buffer against")
    print("  ok    the buffer layout is isolated, labelled, and has a "
          "reference mode")

    # Refusals, not silent degradation.
    for needle, what in (
            ("collisionless", "a collider in the manifest"),
            ("on its side", "a Y-up manifest"),
            ("no mesh resource path", "an asset with no mesh")):
        if needle not in mod:
            fail(f"nothing refuses {what}")
    print("  ok    collider, wrong space and missing mesh all refuse")

    for needle in ("test_quarter_turn_matches_lots_handedness_flip",
                   "test_multimesh_floats_is_row_wise_and_pinned",
                   "test_one_multimesh_per_asset_not_per_instance",
                   "test_both_modes_place_things_in_the_same_spot"):
        if needle not in tst:
            fail(f"no test named {needle}")
    print("  ok    the conversion, the assumption and the two modes are "
          "each pinned")

    ver = base64.b64decode(PAYLOAD["level_factory/VERSION"]["b64"])
    if ver != b"0.45.0":
        fail(f"VERSION payload is {ver!r}")
    if PAYLOAD["level_factory/VERSION"]["pre_bytes"] != 6:
        fail("VERSION pre-image is not 6 bytes")
    ch = src("level_factory/CHANGELOG.md")
    if not ch.startswith("## [0.45.0]") or "## [0.44.0]" not in ch:
        fail("CHANGELOG is not 0.45.0 on top of 0.44.0")
    print("  ok    VERSION 0.44.0 -> 0.45.0 with its entry")

    ref = base64.b64decode(next(iter(PAYLOAD.values()))["b64"])
    mut = bytearray(ref)
    mut[len(mut) // 2] ^= 0x20
    if sha(bytes(mut)) == sha(ref):
        fail("a mutated payload hashed identically")
    else:
        print("  ok    one flipped byte changes the hash")

    print("SELFTEST", "PASSED" if bad == 0 else f"FAILED ({bad})")
    return 1 if bad else 0


def main(argv):
    if "--selftest" in argv:
        return selftest()
    root = None
    if "--root" in argv:
        root = os.path.abspath(argv[argv.index("--root") + 1])
    root = root or repo_root()
    if not root:
        print("Could not find the gabagool_factory root. Pass --root <path>.")
        return 2
    print(f"repo root: {root}")
    if "--revert" in argv:
        return revert(root)
    ok, rows = plan(root)
    if "--check" in argv:
        show(rows)
        print("\n--check only: nothing written."
              + ("" if ok else "  RESOLVE THE STOP LINES FIRST."))
        return 0 if ok else 1
    return apply(root)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
